use std::env;use std::fmt;use std::path::{Path,PathBuf};
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum RuntimePlatform{WindowsX64,MacosArm64,MacosX64}
impl RuntimePlatform{pub fn current()->Option<Self>{if cfg!(all(target_os="windows",target_arch="x86_64")){Some(Self::WindowsX64)}else if cfg!(all(target_os="macos",target_arch="aarch64")){Some(Self::MacosArm64)}else if cfg!(all(target_os="macos",target_arch="x86_64")){Some(Self::MacosX64)}else{None}}pub const fn as_str(self)->&'static str{match self{Self::WindowsX64=>"windows-x64",Self::MacosArm64=>"macos-arm64",Self::MacosX64=>"macos-x64"}}}
#[derive(Debug)]pub enum RuntimeError{UnsupportedPlatform,NotFound(PathBuf),MissingLibrary(PathBuf)}
impl fmt::Display for RuntimeError{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{match self{Self::UnsupportedPlatform=>write!(f,"unsupported lixh FFmpeg runtime platform"),Self::NotFound(p)=>write!(f,"FFmpeg runtime directory not found: {}",p.display()),Self::MissingLibrary(p)=>write!(f,"FFmpeg runtime library missing: {}",p.display())}}}impl std::error::Error for RuntimeError{}
#[derive(Debug,Clone)]pub struct FfmpegRuntime{root:PathBuf,platform:RuntimePlatform}
impl FfmpegRuntime{pub fn current()->Result<Self,RuntimeError>{let platform=RuntimePlatform::current().ok_or(RuntimeError::UnsupportedPlatform)?;let root=Self::resolve_root(platform);let runtime=Self{root,platform};runtime.validate()?;Ok(runtime)}pub fn from_root(root:impl Into<PathBuf>)->Result<Self,RuntimeError>{let platform=RuntimePlatform::current().ok_or(RuntimeError::UnsupportedPlatform)?;let runtime=Self{root:root.into(),platform};runtime.validate()?;Ok(runtime)}pub fn root(&self)->&Path{&self.root}pub fn platform(&self)->RuntimePlatform{self.platform}pub fn validate(&self)->Result<(),RuntimeError>{if !self.root.is_dir(){return Err(RuntimeError::NotFound(self.root.clone()))}for path in self.required_libraries(){if !path.is_file(){return Err(RuntimeError::MissingLibrary(path))}}Ok(())}pub fn required_libraries(&self)->Vec<PathBuf>{match self.platform{RuntimePlatform::WindowsX64=>["avcodec","avformat","avutil","swresample","swscale"].iter().filter_map(|n|find_prefixed_file(&self.root,&format!("{n}-"),".dll")).collect(),RuntimePlatform::MacosArm64|RuntimePlatform::MacosX64=>["libavcodec","libavformat","libavutil","libswresample","libswscale"].iter().filter_map(|n|find_prefixed_file(&self.root,n,".dylib")).collect()}}fn resolve_root(platform:RuntimePlatform)->PathBuf{if let Ok(p)=env::var("LIXH_FFMPEG_RUNTIME_DIR"){return PathBuf::from(p)}if let Ok(p)=env::var("TAURI_RESOURCE_DIR"){let root=PathBuf::from(p);let direct=root.join("ffmpeg").join(platform.as_str());if direct.is_dir(){return direct}let nested=root.join("resources").join("ffmpeg").join(platform.as_str());if nested.is_dir(){return nested}return direct}PathBuf::from("runtime").join(platform.as_str())}}
fn find_prefixed_file(root:&Path,prefix:&str,suffix:&str)->Option<PathBuf>{let entries=std::fs::read_dir(root).ok()?;entries.filter_map(Result::ok).map(|e|e.path()).find(|p|p.file_name().and_then(|n|n.to_str()).map(|n|n.starts_with(prefix)&&n.ends_with(suffix)).unwrap_or(false))}